module arcade_expected(\n    input clk,\n    input rst_n,\n    input start,\n    input signed [15:0] v [0:9],\n    input [15:0] p0 [0:9],\n    input [15:0] p1 [0:9],\n    input [15:0] p2 [0:9],\n    input [15:0] p3 [0:9],\n    input [15:0] p4 [0:9],\n    output reg signed [31:0] result,\n    output reg done\n);\n\n    // FSM States\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] INIT           = 4'd1;\n    localparam [3:0] FORWARD_ELIM   = 4'd2;\n    localparam [3:0] ROW_SWAP       = 4'd3;\n    localparam [3:0] ROW_SCALE      = 4'd4;\n    localparam [3:0] ROW_ELIM       = 4'd5;\n    localparam [3:0] BACK_SUBST     = 4'd6;\n    localparam [3:0] FINISH         = 4'd7;\n\n    reg [3:0] state, next_state;\n    reg [15:0] ctrl_counter;\n    reg [3:0] pivot_row, pivot_col;\n    reg [3:0] curr_row, curr_col;\n    reg signed [31:0] matrix [0:9] [0:10];\n    reg signed [31:0] max_val;\n    reg [3:0] max_row;\n    integer i, j, k;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            ctrl_counter <= 16'd0;\n            pivot_row <= 4'd0;\n            pivot_col <= 4'd0;\n            curr_row <= 4'd0;\n            curr_col <= 4'd0;\n            max_val <= 32'sd0;\n            max_row <= 4'd0;\n            done <= 1'b0;\n            result <= 32'sd0;\n            // Initialize matrix to zero\n            for (i = 0; i < 10; i = i + 1) begin\n                for (j = 0; j < 11; j = j + 1) begin\n                    matrix[i][j] <= 32'sd0;\n                end\n            end\n        end else begin\n            ctrl_counter <= ctrl_counter + 16'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    ctrl_counter <= 16'd0;\n                    if (start) begin\n                        next_state <= INIT;\n                        // Initialize matrix with probabilities\n                        for (i = 0; i < 10; i = i + 1) begin\n                            matrix[i][i] <= {16'd65535, 16'd0}; // 1.0 in Q16.16\n                        end\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                INIT: begin\n                    // Build initial augmented matrix\n                    if (ctrl_counter < 16'd10) begin\n                        // E[i] = p4[i]*v[i] + sum of neighbor terms\n                        i = ctrl_counter;\n                        matrix[i][10] <= {v[i], 16'd0} * p4[i]; // v[i] in Q8.8 * p4 in Q0.16\n                        if (i != 0) begin\n                            matrix[i][0] <= -({16'd0, p0[i]}); // TL neighbor\n                        end\n                        if (i != 0) begin\n                            matrix[i][1] <= -({16'd0, p1[i]}); // TR neighbor\n                        end\n                        if (i > 2) begin\n                            matrix[i][i-3] <= -({16'd0, p2[i]}); // BL neighbor\n                        end\n                        if (i > 3) begin\n                            matrix[i][i-4] <= -({16'd0, p3[i]}); // BR neighbor\n                        end\n                        next_state <= INIT;\n                    end else begin\n                        next_state <= FORWARD_ELIM;\n                        pivot_row <= 4'd0;\n                    end\n                end\n\n                FORWARD_ELIM: begin\n                    if (pivot_row < 4'd9) begin\n                        next_state <= ROW_SWAP;\n                        max_val <= 32'd0;\n                        max_row <= pivot_row;\n                    end else begin\n                        next_state <= BACK_SUBST;\n                    end\n                end\n\n                ROW_SWAP: begin\n                    // Find pivot in current column\n                    for (i = pivot_row; i < 10; i = i + 1) begin\n                        if ($signed(matrix[i][pivot_row]) > $signed(max_val)) begin\n                            max_val <= matrix[i][pivot_row];\n                            max_row <= i;\n                        end\n                    end\n                    next_state <= ROW_SCALE;\n                    curr_row <= max_row;\n                end\n\n                ROW_SCALE: begin\n                    // Scale pivot row\n                    if (curr_row != pivot_row) begin\n                        for (j = 0; j < 11; j = j + 1) begin\n                            matrix[pivot_row][j] <= matrix[curr_row][j];\n                            matrix[curr_row][j] <= 32'sd0;\n                        end\n                    end\n                    next_state <= ROW_ELIM;\n                    curr_row <= pivot_row + 4'd1;\n                end\n\n                ROW_ELIM: begin\n                    // Eliminate rows below pivot\n                    if (curr_row < 4'd10) begin\n                        // row[curr_row] = row[curr_row] - (matrix[curr_row][pivot_col]/matrix[pivot_row][pivot_col]) * pivot_row\n                        // (Fixed-point division implementation needed here)\n                        next_state <= ROW_ELIM;\n                        curr_row <= curr_row + 4'd1;\n                    end else begin\n                        next_state <= FORWARD_ELIM;\n                        pivot_row <= pivot_row + 4'd1;\n                    end\n                end\n\n                BACK_SUBST: begin\n                    // Back-substitution to solve for E[0]\n                    if (pivot_row > 4'd0) begin\n                        pivot_row <= pivot_row - 4'd1;\n                        for (j = pivot_row + 1; j < 10; j = j + 1) begin\n                            matrix[pivot_row][10] <= matrix[pivot_row][10] - matrix[pivot_row][j] * matrix[j][10];\n                            matrix[pivot_row][j] <= 32'sd0;\n                        end\n                        matrix[pivot_row][10] <= matrix[pivot_row][10] / matrix[pivot_row][pivot_row];\n                    end else begin\n                        result <= matrix[0][10]; // Final result in Q16.16\n                        next_state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule